    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TokenizerError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .MissingConfig
        case 2: return .ChatTemplate(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .MismatchedConfig(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TokenizerError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .MissingConfig:
            writeInt(&buf, Int32(1))
        
        
        case let .ChatTemplate(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .MismatchedConfig(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


